func getTerminalSize() (int,int) {
 // Try ioctl
 type winsize struct {
  Row, Col, Xpixel, Ypixel uint16
 }
 fd := int(os.Stdout.Fd())
 var ws winsize
 _,_,_ = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5413), uintptr(unsafe.Pointer(&ws)))
 if ws.Col !=0 && ws.Row !=0 {
  return int(ws.Col), int(ws.Row)
 }
 fd = int(os.Stdin.Fd())
 _,_,_ = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5413), uintptr(unsafe.Pointer(&ws)))
 if ws.Col !=0 && ws.Row !=0 {
  return int(ws.Col), int(ws.Row)
 }
 fd = int(os.Stderr.Fd())
 _,_,_ = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5413), uintptr(unsafe.Pointer(&ws)))
 if ws.Col !=0 && ws.Row !=0 {
  return int(ws.Col), int(ws.Row)
 }
 return 0,0
}

