func getTerminalSize() (int,int) {
 type winsize struct {
  Row, Col, Xpixel, Ypixel uint16
 }
 // try stdout
 for _, fd := range []int{int(os.Stdout.Fd()), int(os.Stdin.Fd()), int(os.Stderr.Fd())} {
  var ws winsize
  _,_,_ = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5413), uintptr(unsafe.Pointer(&ws)))
  if ws.Col!=0 && ws.Row!=0 {
   return int(ws.Col), int(ws.Row)
  }
 }
 // try COLUMNS LINES env
 colsStr := os.Getenv("COLUMNS")
 linesStr := os.Getenv("LINES")
 if colsStr!="" && linesStr!="" {
  c,_ := strconv.Atoi(colsStr)
  r,_ := strconv.Atoi(linesStr)
  if c!=0 && r!=0 {
   return c,r
  }
 }
 // try stty size
 cmd := exec.Command("stty","size")
 cmd.Stdin = os.Stdin
 out, err := cmd.Output()
 if err==nil {
  parts := strings.Fields(string(out))
  if len(parts)==2 {
   r,_ := strconv.Atoi(parts[0])
   c,_ := strconv.Atoi(parts[1])
   if c!=0 && r!=0 {
    return c,r
   }
  }
 }
 // try tput cols lines
 cmd = exec.Command("tput","cols")
 out, err = cmd.Output()
 cols := 0
 if err==nil {
  cols,_ = strconv.Atoi(strings.TrimSpace(string(out)))
 }
 cmd = exec.Command("tput","lines")
 out, err = cmd.Output()
 rows := 0
 if err==nil {
  rows,_ = strconv.Atoi(strings.TrimSpace(string(out)))
 }
 if cols!=0 && rows!=0 {
  return cols, rows
 }
 return 0,0
}

func hasColorSupport() (bool24, bool8 bool) {
 colorterm := os.Getenv("COLORTERM")
 term := os.Getenv("TERM")
 if strings.Contains(colorterm, "truecolor") || strings.Contains(colorterm, "24bit") {
  if term != "screen" {
   bool24 = true
  }
 }
 if !bool24 {
  if strings.Contains(term, "xterm") {
   bool8 = true
  } else if strings.Contains(term, "256color") {
   bool8 = true
  } else if term == "screen" {
   bool8 = true
  }
 }
 return
}

func parseDimensions(s string) (int,int,error) {
 parts := strings.Split(s, ",")
 if len(parts)!=2 {
  return 0,0,fmt.Errorf("requires 2 dimensions, got %d", len(parts))
 }
 wStr := strings.TrimSpace(parts[0])
 hStr := strings.TrimSpace(parts[1])
 if wStr=="" || hStr=="" {
  return 0,0,fmt.Errorf("invalid argument %q for \"-d, --dimensions\" flag: strconv.Atoi: parsing \"\": invalid syntax", s)
 }
 w, err1 := strconv.Atoi(wStr)
 h, err2 := strconv.Atoi(hStr)
 if err1!=nil {
  return 0,0,fmt.Errorf("invalid argument %q for \"-d, --dimensions\" flag: %v", s, err1)
 }
 if err2!=nil {
  return 0,0,fmt.Errorf("invalid argument %q for \"-d, --dimensions\" flag: %v", s, err2)
 }
 return w,h,nil
}

