}

func parseBMP(data []byte)(image.Image,error){
 if len(data)<54 { return nil, fmt.Errorf("bmp too small") }
 if data[0]!='B' || data[1]!='M' { return nil, fmt.Errorf("not bmp") }
 off:=int(data[10])|int(data[11])<<8|int(data[12])<<16|int(data[13])<<24
 hSize:=int(data[14])|int(data[14+1])<<8|int(data[14+2])<<16|int(data[14+3])<<24
 if hSize!=40 { return nil, fmt.Errorf("unsupported bmp header %d", hSize) }
 w:=int(data[18])|int(data[19])<<8|int(data[20])<<16|int(data[21])<<24
 h:=int(data[22])|int(data[22+1])<<8|int(data[22+2])<<16|int(data[22+3])<<24
 planes:=int(data[26])|int(data[27])<<8; bpp:=int(data[28])|int(data[29])<<8; comp:=int(data[30])|int(data[31])<<8|int(data[32])<<16|int(data[33])<<24
 if planes!=1 || bpp!=24 || comp!=0 { return nil, fmt.Errorf("unsupported bmp format") }
 if w<=0 || h==0 { return nil, fmt.Errorf("invalid bmp") }
 absH:=h; if h<0 { absH=-h }
 rowSize:=((w*3+3)/4)*4
 if len(data) < off+absH*rowSize { return nil, fmt.Errorf("bmp truncated") }
 img:=image.NewRGBA(image.Rect(0,0,w,absH))
 for y:=0; y<absH; y++{
  srcY:=y
  if h>0 { srcY=absH-1-y }
  rowOff:=off+srcY*rowSize
  for x:=0; x<w; x++{
   b:=data[rowOff+x*3]; g:=data[rowOff+x*3+1]; r:=data[rowOff+x*3+2]
   img.Set(x,y, color.RGBA{R:r,G:g,B:b,A:255})
  }
 }
 return img,nil
}

func decodeImage(data []byte)(image.Image,string,error){
 if len(data)>=2 && data[0]=='B' && data[1]=='M' {
  img,err:=parseBMP(data); if err==nil { return img,"bmp",nil }
 }
 img,fmtStr,err:=image.Decode(bytes.NewReader(data))
 if err==nil { return img,fmtStr,nil }
 return nil,"",fmt.Errorf("image: unknown format")
}

func grayFromRGB(r,g,b uint8)uint8{
 r1:=int(r)<<8|int(r); g1:=int(g)<<8|int(g); b1:=int(b)<<8|int(b)
 y:=(19595*r1+38470*g1+7471*b1+1<<15)>>24
 return uint8(y)
}

func resizeImage(src image.Image, newW,newH int)image.Image{
 if newW<=0 || newH<=0 {
  var s []int; _=s[0]
 }
 srcB:=src.Bounds(); srcW:=srcB.Dx(); srcH:=srcB.Dy()
 dst:=image.NewRGBA(image.Rect(0,0,newW,newH))
 for y:=0; y<newH; y++{
  fy:=float64(y)*float64(srcH)/float64(newH); sy:=int(fy); dy:=fy-float64(sy)
  if sy>=srcH-1 { sy=srcH-2 }; if sy<0 { sy=0 }
  for x:=0; x<newW; x++{
   fx:=float64(x)*float64(srcW)/float64(newW); sx:=int(fx); dx:=fx-float64(sx)
   if sx>=srcW-1 { sx=srcW-2 }; if sx<0 { sx=0 }
   c00:=src.At(srcB.Min.X+sx, srcB.Min.Y+sy); c10:=src.At(srcB.Min.X+sx+1, srcB.Min.Y+sy); c01:=src.At(srcB.Min.X+sx, srcB.Min.Y+sy+1); c11:=src.At(srcB.Min.X+sx+1, srcB.Min.Y+sy+1)
   r00,g00,b00,a00:=c00.RGBA(); r10,g10,b10,a10:=c10.RGBA(); r01,g01,b01,a01:=c01.RGBA(); r11,g11,b11,a11:=c11.RGBA()
   r0:=float64(r00)*(1-dx)+float64(r10)*dx; r1:=float64(r01)*(1-dx)+float64(r11)*dx; r:=r0*(1-dy)+r1*dy
   g0:=float64(g00)*(1-dx)+float64(g10)*dx; g1:=float64(g01)*(1-dx)+float64(g11)*dx; g:=g0*(1-dy)+g1*dy
   b0:=float64(b00)*(1-dx)+float64(b10)*dx; b1:=float64(b01)*(1-dx)+float64(b11)*dx; b:=b0*(1-dy)+b1*dy
   a0:=float64(a00)*(1-dx)+float64(a10)*dx; a1:=float64(a01)*(1-dx)+float64(a11)*dx; a:=a0*(1-dy)+a1*dy
   dst.Set(x,y, color.RGBA64{R:uint16(r),G:uint16(g),B:uint16(b),A:uint16(a)})
  }
 }
 return dst
}

func computeDimensions(imgW,imgH int, flags Flags)(int,int){
 if flags.full {
  cols,rows:=getTerminalSize()
  if cols==0 || rows==0 { var s []int; _=s[0] }
  outW:=cols-1
  outH:=int(float64(outW)*float64(imgH)/float64(imgW)*0.5)
  if outH<1 { outH=1 }
  return outW,outH
 }
 if flags.dimensionsSet { return flags.dimW,flags.dimH }
 if flags.widthSet {
  outW:=flags.width
  outH:=int(float64(outW)*float64(imgH)/float64(imgW)*0.5)
  if outH<1 { outH=1 }
  return outW,outH
 }
 if flags.heightSet {
  outH:=flags.height
  outW:=int(float64(outH)*float64(imgW)/float64(imgH)*2)
  if outW<1 { outW=1 }
  return outW,outH
 }
 cols,rows:=getTerminalSize()
 if cols==0 || rows==0 { var s []int; _=s[0] }
 hTry:=rows-1
 wTry:=int(float64(hTry)*float64(imgW)/float64(imgH)*2)
 if wTry <= cols-1 {
  return wTry,hTry
 } else {
  outW:=cols-1
  outH:=int(float64(outW)*float64(imgH)/float64(imgW)*0.5)
  if outH<1 { outH=1 }
  return outW,outH
 }
}

func rgbTo256(r,g,b uint8)int{
 if r==g && g==b {
  if r<8 { return 16 }
  if r>248 { return 231 }
  return int(math.Round(float64(r-8)/247*23)) + 232
 }
 r6:=int(float64(r)/255*5+0.5); g6:=int(float64(g)/255*5+0.5); b6:=int(float64(b)/255*5+0.5)
 if r6<0 { r6=0 }; if r6>5 { r6=5 }
 if g6<0 { g6=0 }; if g6>5 { g6=5 }
 if b6<0 { b6=0 }; if b6>5 { b6=5 }
 return 16+36*r6+6*g6+b6
}

