 }

 has24, has8 := hasColorSupport()
 needColor := flags.color || flags.grayscale || flags.fontColorSet
 if needColor {
  if !has24 && !has8 { fmt.Printf("Error: your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available\n\n"); return }
 }

 checkSavePath := func(p string)bool{
  if p=="." { return true }
