      packed2:=data[idx+9]; idx+=10
      hasLCT:=(packed2&0x80)!=0; lctSize:=0
      if hasLCT{ size:=packed2&0x07; lctSize=3*(1<<(size+1)) }
      idx+=lctSize
      if idx>=len(data){ break }
      idx++
      for{
       if idx>=len(data){ break }
       blockSize:=int(data[idx]); idx++
       if blockSize==0{ break }
       idx+=blockSize
