    for bx:=0; bx<outW; bx++{
     bits:=0
     for dy:=0; dy<4; dy++{
      for dx:=0; dx<2; dx++{
       px:=bx*2+dx; py:=by*4+dy
       if px>=scaledW||py>=scaledH{ continue }
       var bright float64
       if flags.dither{ bright=grayMat[py][px] } else {
        c:=scaled.At(px,py); r,g,b,_:=c.RGBA(); rr:=uint8(r>>8); gg:=uint8(g>>8); bb:=uint8(b>>8); bright=float64(grayFromRGB(rr,gg,bb))
       }
