     }
     newLines[li]=string(runes)
    }
    brailleLines=newLines
   }
  } else {
   scaled:=resizeImage(srcImg, outW, outH)
   asciiLines=make([]string, outH)
   colorMatrix=make([][][3]uint8, outH)
