     runes:=[]rune(line)
     for l,r:=0,len(runes)-1; l<r; l,r=l+1,r-1{ runes[l],runes[r]=runes[r],runes[l] }
     asciiLines[i]=string(runes)
     row:=colorMatrix[i]
     for l,r:=0,len(row)-1; l<r; l,r=l+1,r-1{ row[l],row[r]=row[r],row[l] }
    }
   }
   if flags.flipY{
    for l,r:=0,len(asciiLines)-1; l<r; l,r=l+1,r-1{
     asciiLines[l],asciiLines[r]=asciiLines[r],asciiLines[l]
     colorMatrix[l],colorMatrix[r]=colorMatrix[r],colorMatrix[l]
    }
   }
  }

  useColor:=false; useGrayscale:=false; useFontColor:=false
  if flags.color{ useColor=true } else if flags.grayscale{ useGrayscale=true } else if flags.fontColorSet{ useFontColor=true }

  var outputBuilder strings.Builder

  if flags.braille{
   if useColor||useGrayscale||useFontColor{
    scaledW:=outW*2; scaledH:=outH*4
    scaled:=resizeImage(srcImg, scaledW, scaledH)
    brailleColorMatrix:=make([][][3]uint8, outH)
    for by:=0; by<outH; by++{
     row:=make([][3]uint8, outW)
     for bx:=0; bx<outW; bx++{
      var sumR,sumG,sumB int; cnt:=0
      for dy:=0; dy<4; dy++{
       for dx:=0; dx<2; dx++{
        px:=bx*2+dx; py:=by*4+dy
        if px>=scaledW||py>=scaledH{ continue }
        c:=scaled.At(px,py); r,g,b,_:=c.RGBA(); sumR+=int(r>>8); sumG+=int(g>>8); sumB+=int(b>>8); cnt++
       }
