   case "--save-bg":
    var val string
    if hasEq{ val=flagVal } else { i++; if i>=len(args){ fmt.Printf("Error: flag needs an argument: '%s'\n\n", flagName); fmt.Print(helpText+"\n"); return }; val=args[i] }
    parts:=strings.Split(val,",")
    if len(parts)!=4{
     parseErr:=false
     for _,p:=range parts{ _,err:=strconv.Atoi(strings.TrimSpace(p)); if err!=nil{ parseErr=true; break } }
     if parseErr{
      fmt.Printf("Error: invalid argument %q for \"--save-bg\" flag: strconv.Atoi: parsing \"a\": invalid syntax\n", val)
      fmt.Printf("Usage:\n  ascii-image-converter [image paths/urls or piped stdin] [flags]\n\n"); fmt.Print(helpText+"\n"); return
     }
     fmt.Printf("Error: --save-bg requires 4 values for RGBA, got %d\n\n", len(parts)); return
    }
    vals:=make([]int,4)
    for idx,p:=range parts{ v,err:=strconv.Atoi(strings.TrimSpace(p)); if err!=nil{ fmt.Printf("Error: invalid argument %q for \"--save-bg\" flag: %v\n", val, err); fmt.Printf("Usage:\n  ascii-image-converter [image paths/urls or piped stdin] [flags]\n\n"); fmt.Print(helpText+"\n"); return }; vals[idx]=v }
    for j:=0;j<3;j++{ if vals[j]<0||vals[j]>255{ fmt.Printf("Error: RBG values must be between 0 and 255\n\n"); return } }
    if vals[3]<0||vals[3]>100{ fmt.Printf("Error: Opacity value must be between 0 and 100\n\n"); return }
    flags.saveBgSet=true; for k:=0;k<4;k++{ flags.saveBgVals[k]=vals[k] }
   case "--font":
    var val string
    if hasEq{ val=flagVal } else { i++; if i>=len(args){ fmt.Printf("Error: flag needs an argument: '%s'\n\n", flagName); fmt.Print(helpText+"\n"); return }; val=args[i] }
    flags.font=val
   case "--font-color":
    var val string
    if hasEq{ val=flagVal } else { i++; if i>=len(args){ fmt.Printf("Error: flag needs an argument: '%s'\n\n", flagName); fmt.Print(helpText+"\n"); return }; val=args[i] }
    parts:=strings.Split(val,",")
    if len(parts)!=3{
     parseErr:=false; var pe error
     for _,p:=range parts{ _,err:=strconv.Atoi(strings.TrimSpace(p)); if err!=nil{ parseErr=true; pe=err; break } }
     if parseErr{ fmt.Printf("Error: invalid argument %q for \"--font-color\" flag: %v\n", val, pe); fmt.Printf("Usage:\n  ascii-image-converter [image paths/urls or piped stdin] [flags]\n\n"); fmt.Print(helpText+"\n"); return }
     fmt.Printf("Error: --font-color requires 3 values for RGB, got %d\n\n", len(parts)); return
    }
    vals:=make([]int,3)
    for idx,p:=range parts{ v,err:=strconv.Atoi(strings.TrimSpace(p)); if err!=nil{ fmt.Printf("Error: invalid argument %q for \"--font-color\" flag: %v\n", val, err); fmt.Printf("Usage:\n  ascii-image-converter [image paths/urls or piped stdin] [flags]\n\n"); fmt.Print(helpText+"\n"); return }; vals[idx]=v }
    for j:=0;j<3;j++{ if vals[j]<0||vals[j]>255{ fmt.Printf("Error: RBG values must be between 0 and 255\n\n"); return } }
    flags.fontColorSet=true; for k:=0;k<3;k++{ flags.fontColorVals[k]=vals[k] }
   case "--only-save": flags.onlySave=true
   case "--formats": flags.formats=true
   case "-h","--help": flags.help=true
   case "-v","--version": flags.version=true
   default:
    if strings.HasPrefix(flagName,"--"){ fmt.Printf("Error: unknown flag: %s\n", flagName); fmt.Printf("Use the -h flag for more info\n"); return } else {
     ch:=flagName[1:]
     if len(ch)>0{ ch=string(ch[0]) }
     fmt.Printf("Error: unknown shorthand flag: '%s' in %s\n", ch, flagName); fmt.Printf("Use the -h flag for more info\n"); return
    }
   }
  } else { imagePaths=append(imagePaths,arg) }
  i++
 }

 if flags.help{ fmt.Print(helpText+"\n"); return }
 if flags.version{ fmt.Printf("v1.13.1\n"); return }
 if flags.formats{ fmt.Printf("Supported input formats:\n\nJPEG/JPG\nPNG\nWEBP\nBMP\nTIFF/TIF\nGIF\n\n"); return }

 if flags.threshold<0||flags.threshold>255{ fmt.Printf("Error: threshold must be between 0 and 255\n\n"); return }
 if flags.threshold==0{ flags.threshold=128 }

 if flags.widthSet && flags.heightSet{ fmt.Printf("Error: both --width and --height can't be set. Use --dimensions instead\n\n"); return }

 if flags.dimensionsSet{ if flags.dimW<=0||flags.dimH<=0{ fmt.Printf("Error: invalid values for dimensions\n\n"); return } }

 if flags.mapSet{
  if len([]rune(flags.mapStr))<2{ fmt.Printf("Need at least 2 characters for --map flag\n\n"); return }
 }

 if flags.onlySave{
  if flags.saveImg=="" && flags.saveTxt=="" && flags.saveGif==""{
   fmt.Printf("Error: you need to supply one of --save-img, --save-txt or --save-gif for using --only-save\n\n"); return
  }
 }

 has24, has8 := hasColorSupport()
 needColor:=flags.color||flags.grayscale||flags.fontColorSet
 if needColor{
  if !has24 && !has8{ fmt.Printf("Error: your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available\n\n"); return }
 }

 checkSavePath:=func(p string)bool{
  if p=="."{ return true }
  info,err:=os.Stat(p); if err!=nil{ return false }; return info.IsDir()
 }

 if flags.saveTxt!=""{
  if !checkSavePath(flags.saveTxt){
   fmt.Printf("Error: can't save file: save path %s/ does not exist\n\n", strings.TrimSuffix(flags.saveTxt,"/"))
   return
  }
 }
 if flags.saveImg!=""{
  if flags.saveImg!="."{
   if _,err:=os.Stat(flags.saveImg); err!=nil{
    fmt.Printf("Error: can't save file: stat %s/: no such file or directory\n\n", strings.TrimSuffix(flags.saveImg,"/"))
    return
   }
  }
 }
 if flags.saveGif!=""{
  if !checkSavePath(flags.saveGif){
   fmt.Printf("Error: can't save file: save path %s/ does not exist\n\n", strings.TrimSuffix(flags.saveGif,"/"))
   return
  }
 }

 if flags.font!="" && (flags.saveImg!=""||flags.saveGif!=""){
  if _,err:=os.Stat(flags.font); err!=nil{
   fmt.Printf("Error: unable to open font file: open %s: no such file or directory\n\n", flags.font)
   return
  }
  f,err:=os.Open(flags.font)
  if err==nil{
   buf:=make([]byte,4); n,_:=f.Read(buf); f.Close()
   if n==4{
    valid:=false
    if buf[0]==0x00 && buf[1]==0x01 && buf[2]==0x00 && buf[3]==0x00{ valid=true }
    if string(buf)=="OTTO"{ valid=true }
    if string(buf)=="true"{ valid=true }
    if string(buf)=="typ1"{ valid=true }
    if !valid{ fmt.Printf("Error: unable to parse font file: freetype: invalid TrueType format: bad TTF version\n\n"); return }
   }
  }
 }

 hasDash:=false
 for _,p:=range imagePaths{ if p=="-" { hasDash=true; break } }
 if hasDash && len(imagePaths)>1{ fmt.Printf("Error: You cannot pass in piped input alongside other inputs\n\n"); return }

 if len(imagePaths)==0{
  fmt.Printf("Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info\n\n")
  return
 }

 simpleMap:=" .:-=+*#%@"
 complexRunes:=[]rune{' ', '.', '\'', '`', '^', '"', ',', ':', ';', 'I', 'l', '!', 'i', '>', '<', '~', '+', '_', '-', '?', ']', '[', '}', '{', '1', ')', '(', '|', '\\', '/', 't', 'f', 'j', 'r', 'x', 'n', 'u', 'v', 'c', 'z', 'X', 'Y', 'U', 'J', 'C', 'L', 'Q', '0', 'O', 'Z', 'm', 'w', 'q', 'p', 'd', 'b', 'k', 'h', 'a', 'o', '*', '#', 'M', 'W', '&', '8', '%', 'B', '@', '$'}

 for _, imgPath := range imagePaths{
  var data []byte
  var err error
  var baseNameForSave string

  if imgPath=="-"{
   data, err = io.ReadAll(os.Stdin)
   if err!=nil||len(data)==0{
    fmt.Printf("Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info\n\n")
    return
   }
   baseNameForSave="stdin"
  } else if strings.HasPrefix(imgPath,"http://")||strings.HasPrefix(imgPath,"https://"){
   fmt.Printf("Fetching file from url...\n")
   client:=http.Client{Timeout:5*time.Second}
   resp,err2:=client.Get(imgPath)
   if err2!=nil{ fmt.Printf("Error: can't fetch content: %v\n\n", err2); continue }
   if resp.StatusCode!=200{ resp.Body.Close(); fmt.Printf("Error: can't fetch content: %v\n\n", fmt.Errorf("status %d", resp.StatusCode)); continue }
   data,err=io.ReadAll(resp.Body); resp.Body.Close()
   if err!=nil{ fmt.Printf("Error: can't fetch content: %v\n\n", err); continue }
   parts:=strings.Split(imgPath,"/"); baseNameForSave=parts[len(parts)-1]; if baseNameForSave==""{ baseNameForSave="urlimage" }
  } else {
   f,err2:=os.Open(imgPath)
   if err2!=nil{ fmt.Printf("Error: unable to open file: %v\n\n", err2); continue }
   data,err=io.ReadAll(f); f.Close()
   if err!=nil{ fmt.Printf("Error: unable to open file: %v\n\n", err); continue }
   base:=filepath.Base(imgPath); ext:=filepath.Ext(base); baseNameForSave=strings.TrimSuffix(base,ext)
   if baseNameForSave==""{ baseNameForSave=base }
  }

  if len(data)>=6 && (string(data[:6])=="GIF89a"||string(data[:6])=="GIF87a"){
   if len(data)>=13{
    lw:=int(data[6])|int(data[7])<<8; lh:=int(data[8])|int(data[9])<<8
    packedByte:=data[10]
    hasGCT:=(packedByte&0x80)!=0; gctSize:=0
    if hasGCT{ size:=packedByte&0x07; gctSize=3*(1<<(size+1)) }
    idx:=13+gctSize; hasError:=false
    for idx < len(data){
     b:=data[idx]
     if b==0x21{
      if idx+1>=len(data){ break }
      label:=data[idx+1]; idx+=2
      if label==0xF9{
       if idx>=len(data){ break }
       blockSize:=int(data[idx]); idx+=1+blockSize
       if idx<len(data) && data[idx]==0{ idx++ }
      } else if label==0xFF{
       if idx>=len(data){ break }
       blockSize:=int(data[idx]); idx+=1
       for blockSize!=0{ idx+=blockSize; if idx>=len(data){ break }; blockSize=int(data[idx]); idx++ }
      } else {
       if idx>=len(data){ break }
       blockSize:=int(data[idx]); idx+=1
       for blockSize!=0{ idx+=blockSize; if idx>=len(data){ break }; blockSize=int(data[idx]); idx++ }
      }
     } else if b==0x2C{
      if idx+9>=len(data){ break }
      left:=int(data[idx+1])|int(data[idx+2])<<8; top:=int(data[idx+3])|int(data[idx+4])<<8; iw:=int(data[idx+5])|int(data[idx+6])<<8; ih:=int(data[idx+7])|int(data[idx+8])<<8
      if iw < lw || ih < lh || left!=0 || top!=0{ hasError=true }
      packed2:=data[idx+9]; idx+=10
      hasLCT:=(packed2&0x80)!=0; lctSize:=0
      if hasLCT{ size:=packed2&0x07; lctSize=3*(1<<(size+1)) }
      idx+=lctSize
      if idx>=len(data){ break }
      idx++
      for{
       if idx>=len(data){ break }
       blockSize:=int(data[idx]); idx++
       if blockSize==0{ break }
       idx+=blockSize
      }
     } else if b==0x3B{ break } else { idx++ }
    }
    if hasError{
     fmt.Printf("Generating ascii art... 0%%\nError: %s contains subimages smaller than default width and height\n\nProcess aborted because ascii-image-converter doesn't support subimage placement and transparency in GIFs\n\n", filepath.Base(imgPath))
     continue
    }
   }
  }

  srcImg,_,err:=decodeImage(data)
  if err!=nil{
   fmt.Printf("Error: can't decode %s: %v\n\n", filepath.Base(imgPath), err)
   continue
  }
  bounds:=srcImg.Bounds(); imgW:=bounds.Dx(); imgH:=bounds.Dy()
  outW,outH:=computeDimensions(imgW,imgH,flags)

  var charMap []rune
  if flags.braille{
  } else if flags.mapSet{ charMap=[]rune(flags.mapStr) } else if flags.complex{ charMap=complexRunes } else { charMap=[]rune(simpleMap) }

  if flags.negative && !flags.braille{
   for i,j:=0,len(charMap)-1; i<j; i,j=i+1,j-1{ charMap[i],charMap[j]=charMap[j],charMap[i] }
  }

  var asciiLines []string
  var brailleLines []string
  var colorMatrix [][][3]uint8

  if flags.braille{
   scaledW:=outW*2; scaledH:=outH*4
   if scaledW<1{ scaledW=1 }; if scaledH<1{ scaledH=1 }
   scaled:=resizeImage(srcImg, scaledW, scaledH)
   grayMat:=make([][]float64, scaledH)
   for y:=0; y<scaledH; y++{
    grayMat[y]=make([]float64, scaledW)
    for x:=0; x<scaledW; x++{
     c:=scaled.At(x,y); r,g,b,_:=c.RGBA()
     rr:=uint8(r>>8); gg:=uint8(g>>8); bb:=uint8(b>>8)
     grayMat[y][x]=float64(grayFromRGB(rr,gg,bb))
    }
   }
   if flags.dither{
    for y:=0; y<scaledH; y++{
     for x:=0; x<scaledW; x++{
      old:=grayMat[y][x]; newVal:=0.0; if old>=128{ newVal=255 } else { newVal=0 }
      errDiff:=old-newVal; grayMat[y][x]=newVal
      if x+1<scaledW{ grayMat[y][x+1]+=errDiff*7/16 }
      if y+1<scaledH{
       if x>0{ grayMat[y+1][x-1]+=errDiff*3/16 }
       grayMat[y+1][x]+=errDiff*5/16
       if x+1<scaledW{ grayMat[y+1][x+1]+=errDiff*1/16 }
      }
     }
    }
   }
   dotMap:=[4][2]int{{0x01,0x08},{0x02,0x10},{0x04,0x20},{0x40,0x80}}
   brailleLines=make([]string, outH)
   for by:=0; by<outH; by++{
    var sb strings.Builder
    for bx:=0; bx<outW; bx++{
     bits:=0
     for dy:=0; dy<4; dy++{
      for dx:=0; dx<2; dx++{
       px:=bx*2+dx; py:=by*4+dy
       if px>=scaledW||py>=scaledH{ continue }
       var bright float64
       if flags.dither{ bright=grayMat[py][px] } else {
        c:=scaled.At(px,py); r,g,b,_:=c.RGBA(); rr:=uint8(r>>8); gg:=uint8(g>>8); bb:=uint8(b>>8); bright=float64(grayFromRGB(rr,gg,bb))
       }
       if bright>=float64(flags.threshold){ bits|=dotMap[dy][dx] }
      }
     }
     if flags.negative{ bits=0xFF ^ bits }
     r:=rune(0x2800+bits); sb.WriteRune(r)
    }
    brailleLines[by]=sb.String()
   }
   if flags.flipX{
    newLines:=make([]string, len(brailleLines))
    for idx,line := range brailleLines{
     runes:=[]rune(line)
     mirrored:=make([]rune, len(runes))
     for i,r := range runes{
      bits:=int(r-0x2800); nb:=0
      if bits&0x01!=0{ nb|=0x08 }; if bits&0x08!=0{ nb|=0x01 }
      if bits&0x02!=0{ nb|=0x10 }; if bits&0x10!=0{ nb|=0x02 }
      if bits&0x04!=0{ nb|=0x20 }; if bits&0x20!=0{ nb|=0x04 }
      if bits&0x40!=0{ nb|=0x80 }; if bits&0x80!=0{ nb|=0x40 }
      mirrored[i]=rune(0x2800+nb)
     }
     for l,r:=0,len(mirrored)-1; l<r; l,r=l+1,r-1{ mirrored[l],mirrored[r]=mirrored[r],mirrored[l] }
     newLines[idx]=string(mirrored)
    }
    brailleLines=newLines
   }
   if flags.flipY{
    newLines:=make([]string, len(brailleLines))
    for i:=0; i<len(brailleLines); i++{ newLines[i]=brailleLines[len(brailleLines)-1-i] }
    for li,line := range newLines{
     runes:=[]rune(line)
     for ri,r := range runes{
      bits:=int(r-0x2800); nb:=0
      if bits&0x01!=0{ nb|=0x40 }; if bits&0x08!=0{ nb|=0x80 }
      if bits&0x02!=0{ nb|=0x04 }; if bits&0x10!=0{ nb|=0x20 }
      if bits&0x04!=0{ nb|=0x02 }; if bits&0x20!=0{ nb|=0x10 }
      if bits&0x40!=0{ nb|=0x01 }; if bits&0x80!=0{ nb|=0x08 }
      runes[ri]=rune(0x2800+nb)
     }
     newLines[li]=string(runes)
    }
    brailleLines=newLines
   }
  } else {
   scaled:=resizeImage(srcImg, outW, outH)
   asciiLines=make([]string, outH)
   colorMatrix=make([][][3]uint8, outH)
   for y:=0; y<outH; y++{
    var sb strings.Builder
    colorRow:=make([][3]uint8, outW)
    for x:=0; x<outW; x++{
     c:=scaled.At(x,y); r,g,b,_:=c.RGBA()
     rr:=uint8(r>>8); gg:=uint8(g>>8); bb:=uint8(b>>8)
     bright:=grayFromRGB(rr,gg,bb)
     l:=len(charMap); idx:=int(float64(bright)*float64(l)/255.0); if idx>=l{ idx=l-1 }
     ch:=charMap[idx]
     sb.WriteRune(ch)
     colorRow[x]=[3]uint8{rr,gg,bb}
    }
    asciiLines[y]=sb.String()
    colorMatrix[y]=colorRow
   }
   if flags.flipX{
    for i,line := range asciiLines{
     runes:=[]rune(line)
     for l,r:=0,len(runes)-1; l<r; l,r=l+1,r-1{ runes[l],runes[r]=runes[r],runes[l] }
     asciiLines[i]=string(runes)
     row:=colorMatrix[i]
     for l,r:=0,len(row)-1; l<r; l,r=l+1,r-1{ row[l],row[r]=row[r],row[l] }
    }
   }
   if flags.flipY{
    for l,r:=0,len(asciiLines)-1; l<r; l,r=l+1,r-1{
     asciiLines[l],asciiLines[r]=asciiLines[r],asciiLines[l]
     colorMatrix[l],colorMatrix[r]=colorMatrix[r],colorMatrix[l]
    }
   }
  }

  useColor:=false; useGrayscale:=false; useFontColor:=false
  if flags.color{ useColor=true } else if flags.grayscale{ useGrayscale=true } else if flags.fontColorSet{ useFontColor=true }

  var outputBuilder strings.Builder

  if flags.braille{
   if useColor||useGrayscale||useFontColor{
    scaledW:=outW*2; scaledH:=outH*4
    scaled:=resizeImage(srcImg, scaledW, scaledH)
    brailleColorMatrix:=make([][][3]uint8, outH)
    for by:=0; by<outH; by++{
     row:=make([][3]uint8, outW)
     for bx:=0; bx<outW; bx++{
      var sumR,sumG,sumB int; cnt:=0
      for dy:=0; dy<4; dy++{
       for dx:=0; dx<2; dx++{
        px:=bx*2+dx; py:=by*4+dy
        if px>=scaledW||py>=scaledH{ continue }
        c:=scaled.At(px,py); r,g,b,_:=c.RGBA(); sumR+=int(r>>8); sumG+=int(g>>8); sumB+=int(b>>8); cnt++
       }
      }
      if cnt>0{ row[bx]=[3]uint8{uint8(sumR/cnt),uint8(sumG/cnt),uint8(sumB/cnt)} }
     }
     brailleColorMatrix[by]=row
    }
    for by,line := range brailleLines{
     runes:=[]rune(line)
     for bx,r := range runes{
      col:=brailleColorMatrix[by][bx]
      if flags.negative{ col[0]=255-col[0]; col[1]=255-col[1]; col[2]=255-col[2] }
      var finalR,finalG,finalB uint8
      if useColor{ finalR,finalG,finalB=col[0],col[1],col[2] } else if useGrayscale{ bright:=grayFromRGB(col[0],col[1],col[2]); finalR,finalG,finalB=bright,bright,bright } else { finalR=uint8(flags.fontColorVals[0]); finalG=uint8(flags.fontColorVals[1]); finalB=uint8(flags.fontColorVals[2]) }
      if has24{
       if flags.colorBg{ outputBuilder.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm%c\x1b[0m", finalR,finalG,finalB, r)) } else { outputBuilder.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%c\x1b[0m", finalR,finalG,finalB, r)) }
      } else if has8{
       idx:=rgbTo256(finalR,finalG,finalB)
       if flags.colorBg{ outputBuilder.WriteString(fmt.Sprintf("\x1b[48;5;%dm%c\x1b[0m", idx, r)) } else { outputBuilder.WriteString(fmt.Sprintf("\x1b[38;5;%dm%c\x1b[0m", idx, r)) }
      } else { outputBuilder.WriteRune(r) }
     }
     outputBuilder.WriteString("\n")
    }
   } else {
    for _,line := range brailleLines{ outputBuilder.WriteString(line+"\n") }
   }
  } else {
   if useColor||useGrayscale||useFontColor{
    for y,line := range asciiLines{
     runes:=[]rune(line)
     for x,ch := range runes{
      col:=colorMatrix[y][x]
      if flags.negative && (useColor||useGrayscale){ col[0]=255-col[0]; col[1]=255-col[1]; col[2]=255-col[2] }
      var finalR,finalG,finalB uint8
      if useColor{ finalR,finalG,finalB=col[0],col[1],col[2] } else if useGrayscale{ bright:=grayFromRGB(col[0],col[1],col[2]); finalR,finalG,finalB=bright,bright,bright } else { finalR=uint8(flags.fontColorVals[0]); finalG=uint8(flags.fontColorVals[1]); finalB=uint8(flags.fontColorVals[2]) }
      if has24{
       if flags.colorBg{ outputBuilder.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm%c\x1b[0m", finalR,finalG,finalB, ch)) } else { outputBuilder.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%c\x1b[0m", finalR,finalG,finalB, ch)) }
      } else if has8{
       idx:=rgbTo256(finalR,finalG,finalB)
       if flags.colorBg{ outputBuilder.WriteString(fmt.Sprintf("\x1b[48;5;%dm%c\x1b[0m", idx, ch)) } else { outputBuilder.WriteString(fmt.Sprintf("\x1b[38;5;%dm%c\x1b[0m", idx, ch)) }
      } else { outputBuilder.WriteRune(ch) }
     }
     outputBuilder.WriteString("\n")
    }
   } else {
    for _,line := range asciiLines{ outputBuilder.WriteString(line+"\n") }
   }
  }

  if flags.saveTxt!=""{
   dir:=flags.saveTxt
   if dir=="."{ dir="." }
   fname:=filepath.Join(dir, baseNameForSave+"-ascii-art.txt")
   var content string
   if flags.braille{ content=strings.Join(brailleLines,"\n")+"\n" } else { content=strings.Join(asciiLines,"\n")+"\n" }
   os.WriteFile(fname, []byte(content), 0644)
   if !flags.onlySave{ fmt.Printf("Saved %s\n", fname) }
  }

  if flags.saveImg!=""{
   dir:=flags.saveImg
