func getTerminalSize()(int,int){
 type winsize struct{ Row,Col,Xpixel,Ypixel uint16 }
 for _, fd := range []int{int(os.Stdout.Fd()), int(os.Stdin.Fd()), int(os.Stderr.Fd())}{
  var ws winsize
  _,_,_ = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5413), uintptr(unsafe.Pointer(&ws)))
  if ws.Col!=0 && ws.Row!=0 { return int(ws.Col), int(ws.Row) }
 }
 colsStr:=os.Getenv("COLUMNS"); linesStr:=os.Getenv("LINES")
 if colsStr!="" && linesStr!=""{
  c,_:=strconv.Atoi(colsStr); r,_:=strconv.Atoi(linesStr)
  if c!=0 && r!=0 { return c,r }
 }
 cmd:=exec.Command("stty","size")
 cmd.Stdin=os.Stdin
 out,err:=cmd.Output()
 if err==nil{
  parts:=strings.Fields(string(out))
  if len(parts)==2{
   r,_:=strconv.Atoi(parts[0]); c,_:=strconv.Atoi(parts[1])
   if c!=0 && r!=0 { return c,r }
  }
 }
 cmd=exec.Command("tput","cols")
 out,err=cmd.Output()
 cols:=0
 if err==nil{ cols,_=strconv.Atoi(strings.TrimSpace(string(out))) }
 cmd=exec.Command("tput","lines")
 out,err=cmd.Output()
 rows:=0
 if err==nil{ rows,_=strconv.Atoi(strings.TrimSpace(string(out))) }
 if cols!=0 && rows!=0 { return cols, rows }
 return 0,0
}

