    return
   }
   baseNameForSave="stdin"
  } else if strings.HasPrefix(imgPath,"http://")||strings.HasPrefix(imgPath,"https://"){
   fmt.Printf("Fetching file from url...\n")
   client:=http.Client{Timeout:5*time.Second}
   resp,err2:=client.Get(imgPath)
   if err2!=nil{ fmt.Printf("Error: can't fetch content: %v\n\n", err2); continue }
   if resp.StatusCode!=200{ resp.Body.Close(); fmt.Printf("Error: can't fetch content: %v\n\n", fmt.Errorf("status %d", resp.StatusCode)); continue }
   data,err=io.ReadAll(resp.Body); resp.Body.Close()
   if err!=nil{ fmt.Printf("Error: can't fetch content: %v\n\n", err); continue }
   parts:=strings.Split(imgPath,"/"); baseNameForSave=parts[len(parts)-1]; if baseNameForSave==""{ baseNameForSave="urlimage" }
  } else {
   f,err2:=os.Open(imgPath)
   if err2!=nil{ fmt.Printf("Error: unable to open file: %v\n\n", err2); continue }
   data,err=io.ReadAll(f); f.Close()
   if err!=nil{ fmt.Printf("Error: unable to open file: %v\n\n", err); continue }
   base:=filepath.Base(imgPath); ext:=filepath.Ext(base); baseNameForSave=strings.TrimSuffix(base,ext)
