 if len(parts)!=2{ return 0,0,fmt.Errorf("requires 2 dimensions, got %d", len(parts)) }
 wStr:=strings.TrimSpace(parts[0]); hStr:=strings.TrimSpace(parts[1])
 if wStr==""||hStr==""{ return 0,0,fmt.Errorf("invalid argument %q for \"-d, --dimensions\" flag: strconv.Atoi: parsing \"\": invalid syntax", s) }
 w,err1:=strconv.Atoi(wStr); h,err2:=strconv.Atoi(hStr)
 if err1!=nil{ return 0,0,fmt.Errorf("invalid argument %q for \"-d, --dimensions\" flag: %v", s, err1) }
