 }

 simpleMap:=" .:-=+*#%@"
 complexRunes:=[]rune{' ', '.', '\'', '`', '^', '"', ',', ':', ';', 'I', 'l', '!', 'i', '>', '<', '~', '+', '_', '-', '?', ']', '[', '}', '{', '1', ')', '(', '|', '\\', '/', 't', 'f', 'j', 'r', 'x', 'n', 'u', 'v', 'c', 'z', 'X', 'Y', 'U', 'J', 'C', 'L', 'Q', '0', 'O', 'Z', 'm', 'w', 'q', 'p', 'd', 'b', 'k', 'h', 'a', 'o', '*', '#', 'M', 'W', '&', '8', '%', 'B', '@', '$'}

 for _, imgPath := range imagePaths{
  var data []byte
  var err error
  var baseNameForSave string

  if imgPath=="-"{
   data, err = io.ReadAll(os.Stdin)
   if err!=nil||len(data)==0{
