  }

  if len(data)>=6 && (string(data[:6])=="GIF89a"||string(data[:6])=="GIF87a"){
   if len(data)>=13{
    lw:=int(data[6])|int(data[7])<<8; lh:=int(data[8])|int(data[9])<<8
    packedByte:=data[10]
    hasGCT:=(packedByte&0x80)!=0; gctSize:=0
    if hasGCT{ size:=packedByte&0x07; gctSize=3*(1<<(size+1)) }
    idx:=13+gctSize; hasError:=false
    for idx < len(data){
     b:=data[idx]
     if b==0x21{
      if idx+1>=len(data){ break }
      label:=data[idx+1]; idx+=2
      if label==0xF9{
       if idx>=len(data){ break }
       blockSize:=int(data[idx]); idx+=1+blockSize
       if idx<len(data) && data[idx]==0{ idx++ }
      } else if label==0xFF{
       if idx>=len(data){ break }
       blockSize:=int(data[idx]); idx+=1
       for blockSize!=0{ idx+=blockSize; if idx>=len(data){ break }; blockSize=int(data[idx]); idx++ }
      } else {
       if idx>=len(data){ break }
       blockSize:=int(data[idx]); idx+=1
       for blockSize!=0{ idx+=blockSize; if idx>=len(data){ break }; blockSize=int(data[idx]); idx++ }
