func parseBMP(data []byte)(image.Image,error){
 if len(data)<54{ return nil, fmt.Errorf("bmp too small") }
 if data[0]!='B'||data[1]!='M'{ return nil, fmt.Errorf("not bmp") }
 off:=int(data[10])|int(data[11])<<8|int(data[12])<<16|int(data[13])<<24
 hSize:=int(data[14])|int(data[14+1])<<8|int(data[14+2])<<16|int(data[14+3])<<24
 if hSize!=40{ return nil, fmt.Errorf("unsupported bmp header %d", hSize) }
 w:=int(data[18])|int(data[19])<<8|int(data[20])<<16|int(data[21])<<24
 h:=int(data[22])|int(data[22+1])<<8|int(data[22+2])<<16|int(data[22+3])<<24
 planes:=int(data[26])|int(data[27])<<8; bpp:=int(data[28])|int(data[29])<<8; comp:=int(data[30])|int(data[31])<<8|int(data[32])<<16|int(data[33])<<24
 if planes!=1||bpp!=24||comp!=0{ return nil, fmt.Errorf("unsupported bmp format") }
 if w<=0||h==0{ return nil, fmt.Errorf("invalid bmp") }
 absH:=h; if h<0{ absH=-h }
 rowSize:=((w*3+3)/4)*4
 if len(data) < off+absH*rowSize{ return nil, fmt.Errorf("bmp truncated") }
 img:=image.NewRGBA(image.Rect(0,0,w,absH))
 for y:=0; y<absH; y++{
  srcY:=y
  if h>0{ srcY=absH-1-y }
  rowOff:=off+srcY*rowSize
  for x:=0; x<w; x++{
   b:=data[rowOff+x*3]; g:=data[rowOff+x*3+1]; r:=data[rowOff+x*3+2]
   img.Set(x,y, color.RGBA{R:r,G:g,B:b,A:255})
  }
 }
 return img,nil
}

func decodeImage(data []byte)(image.Image,string,error){
 if len(data)>=2 && data[0]=='B' && data[1]=='M'{
  img,err:=parseBMP(data); if err==nil{ return img,"bmp",nil }
 }
 img,fmtStr,err:=image.Decode(bytes.NewReader(data))
 if err==nil{ return img,fmtStr,nil }
 return nil,"",fmt.Errorf("image: unknown format")
}

func grayFromRGB(r,g,b uint8)uint8{
 r1:=int(r)<<8|int(r); g1:=int(g)<<8|int(g); b1:=int(b)<<8|int(b)
 y:=(19595*r1+38470*g1+7471*b1+1<<15)>>24
 return uint8(y)
}

func lanczos(x float64, a float64)float64{
 if x==0{ return 1 }
 if math.Abs(x)>=a{ return 0 }
 return a*math.Sin(math.Pi*x)*math.Sin(math.Pi*x/a)/(math.Pi*math.Pi*x*x)
}

// 8-bit RGBA helper
func getRGBA8(c color.Color)(r,g,b,a uint8){
 r16,g16,b16,a16:=c.RGBA()
 r=uint8(r16>>8); g=uint8(g16>>8); b=uint8(b16>>8); a=uint8(a16>>8)
 return
}

func resizeImageLanczos(src image.Image, newW,newH int)image.Image{
 if newW<=0||newH<=0{ var s []int; _=s[0] }
 srcB:=src.Bounds(); srcW:=srcB.Dx(); srcH:=srcB.Dy()
 if srcW==newW && srcH==newH{
  dst:=image.NewRGBA(image.Rect(0,0,newW,newH))
  for y:=0;y<newH;y++{
   for x:=0;x<newW;x++{
    dst.Set(x,y, src.At(srcB.Min.X+x, srcB.Min.Y+y))
   }
  }
  return dst
 }
 dst:=image.NewRGBA(image.Rect(0,0,newW,newH))
 scaleX:=float64(srcW)/float64(newW)
 scaleY:=float64(srcH)/float64(newH)
 a:=3.0
 for y:=0; y<newH; y++{
  fy:=(float64(y)+0.5)*scaleY-0.5
  for x:=0; x<newW; x++{
   fx:=(float64(x)+0.5)*scaleX-0.5
   var sumR,sumG,sumB,sumA,sumW float64
   left:=int(math.Floor(fx-a*scaleX))
   right:=int(math.Ceil(fx+a*scaleX))
   top:=int(math.Floor(fy-a*scaleY))
   bottom:=int(math.Ceil(fy+a*scaleY))
   for sy:=top; sy<=bottom; sy++{
    if sy<0||sy>=srcH{ continue }
    wy:=lanczos((float64(sy)-fy)/scaleY, a)
    if wy==0{ continue }
    for sx:=left; sx<=right; sx++{
     if sx<0||sx>=srcW{ continue }
     wx:=lanczos((float64(sx)-fx)/scaleX, a)
     if wx==0{ continue }
     w:=wx*wy
     c:=src.At(srcB.Min.X+sx, srcB.Min.Y+sy)
     r,g,b,a2:=getRGBA8(c)
     sumR+=float64(r)*w
     sumG+=float64(g)*w
     sumB+=float64(b)*w
     sumA+=float64(a2)*w
     sumW+=w
    }
   }
   if sumW!=0{
    sumR/=sumW; sumG/=sumW; sumB/=sumW; sumA/=sumW
   }
   if sumR<0{ sumR=0 }; if sumR>255{ sumR=255 }
   if sumG<0{ sumG=0 }; if sumG>255{ sumG=255 }
   if sumB<0{ sumB=0 }; if sumB>255{ sumB=255 }
   if sumA<0{ sumA=0 }; if sumA>255{ sumA=255 }
   dst.Set(x,y, color.RGBA{R:uint8(sumR+0.5),G:uint8(sumG+0.5),B:uint8(sumB+0.5),A:uint8(sumA+0.5)})
  }
 }
 return dst
}

func resizeImage(src image.Image, newW,newH int)image.Image{
 return resizeImageLanczos(src,newW,newH)
}

func computeDimensions(imgW,imgH int, flags Flags)(int,int){
 if flags.full{
  cols,rows:=getTerminalSize()
  if cols==0||rows==0{ var s []int; _=s[0] }
  outW:=cols-1
  outH:=int(float64(outW)*float64(imgH)/float64(imgW)*0.5)
  if outH<1{ outH=1 }
  return outW,outH
 }
 if flags.dimensionsSet{ return flags.dimW,flags.dimH }
 if flags.widthSet{
  outW:=flags.width
  outH:=int(float64(outW)*float64(imgH)/float64(imgW)*0.5)
