     r,g,b,a2:=getRGBA8(c)
     sumR+=float64(r)*w; sumG+=float64(g)*w; sumB+=float64(b)*w; sumA+=float64(a2)*w; sumW+=w
    }
   }
   if sumW!=0{ sumR/=sumW; sumG/=sumW; sumB/=sumW; sumA/=sumW }
   fmt.Printf("x %d fx %v sumR %v sumW %v => %v\n", x, fx, sumR, sumW, sumR)
  }
 }
}
